  tools.exec_command({cmd:"ls -la /tmp/run-aaf08dfb/data/staging/run-aaf08dfb/src",workdir:"/tmp/run-aaf08dfb",max_output_tokens:3000})
]); for(let i=0;i<rs.length;i++){text(`RESULT ${i+1}`);text(rs[i].status==="fulfilled"?rs[i].value.output:String(rs[i].reason));}

